import Head from 'next/head';
import styles from '@/styles/SubPage.module.css';
import listStyles from '@/styles/ArticleList.module.css';
import { fetchNews } from '@/lib/wp-api';

export async function getStaticProps() {
  const news = await fetchNews();
  return { props: { news } };
}

export default function NewsPage({ news }) {
  return (
    <>
      <Head>
        <title>お知らせ | SSBA</title>
      </Head>
      <div className={styles.wrapper}>
        <div className={styles.titleCard}>
          <div className={styles.titleInner}>
            <h1 className={styles.pageTitle}>お知らせ</h1>
            <p className={styles.pageSub}>NEWS</p>
          </div>
        </div>
        <div className={styles.body}>
          <div className={styles.section}>
            {news.length === 0 ? (
              <p className={listStyles.empty}>お知らせはありません</p>
            ) : (
              <div className={listStyles.grid}>
                {news.map((item) => (
                  <div key={item.id} className={listStyles.card}>
                    <div className={listStyles.cardImage}>
                      <img
                        src={item.image || '/images/eye-catch.webp'}
                        alt={item.title}
                      />
                    </div>
                    <div className={listStyles.cardBody}>
                      <div className={listStyles.cardMeta}>
                        <span className={listStyles.metaDate}>{item.date}</span>
                        {item.tag && (
                          <span className={listStyles.metaTag}>{item.tag}</span>
                        )}
                      </div>
                      <h2 className={listStyles.cardTitle}>{item.title}</h2>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
      </div>
    </>
  );
}
